 XCTestCase.swift
 import XCTest

 class Test: XCTestCase {

     func testSomething() {
         assertAvoidSwimming(isRecentlySeized: true) == .avoidAltogether
         assertAvoidSwimming(isRecentlySeized: false) == .takePrecautions
     }

     func assertAvoidSwimming(isRecentlySeized: Bool, expected: AvoidanceStrategy) {
         let strategy = SwimmingStrategy(recentSeizure: isRecentlySeized).avoidanceStrategy
         XCTAssertEqual(strategy, expected)
     }

 }

 enum AvoidanceStrategy {
     case avoidAltogether
     case takePrecautions
     case none
 }

class SwimmingStrategy {
    var recentSeizure: Bool
    var avoidanceStrategy: AvoidanceStrategy

    init(recentSeizure: Bool) {
        self.recentSeizure = recentSeizure
        determineAvoidanceStrategy()
    }

    func determineAvoidanceStrategy() {
        if recentSeizure {
            avoidanceStrategy = .avoidAltogether
        } else {
            avoidanceStrategy = .takePrecautions
        }
    }
}

