import XCTest

class TestSession: XCTestCase {

    func testAdviceQuality() {
        let session = DoctorSession()
        XCTAssertEqual(session.getAdvice(for: .osteoporosis, with: .celiacDisease), "go gluten-free", "The advice for osteoporosis related to celiac disease is to go gluten-free.")
    }

    func testMultipleApproaches() {
        let session = DoctorSession()
        XCTAssertTrue(session.multipleApproachesNeeded(for: .osteoporosis), "Osteoporosis typically benefits from multiple types of treatment approaches")
    }
}

