 import XCTest

 class QuickTest: XCTestCase {

 func testSymptomsAndDiet() {
  let result = areSymptomsGallstoneRelated("upper right abdomen", "fatty meals")
  XCTAssert(result == true, "This person might have gallstones and should reduce fatty food intake.")
 }
 }

 extension HealthcareAdviceHelper {

 static func areSymptomsGallstoneRelated(_ location: String, _ trigger: String) -> Bool {
  if location == "upper right abdomen" && trigger == "fatty meals" {
   suggestReducedFatIntake()
   return true
  } else {
   suggestGeneralDietChanges()
   return false
  }
 }

 static func suggestReducedFatIntake() {
  print("Start eating less fat to manage symptoms effectively.")
 }

 static func suggestGeneralDietChanges() {
  print("General diet changes could be helpful.")
 }
 }

executing the function `areSymptomsGallstoneRelated` with "upper right abdomen" and "fatty meals" as inputs will return `true`, indicating that the symptoms are likely gallstones and immediate reduction of fat intake is advised for effective management.

